<?php
require_role('admin');$search=input_text($_GET,'q',100,false);$where="d.hasil='alumni'";$args=[];
if($search!==''){$where.=' AND (s.nis LIKE ? OR s.nama_siswa LIKE ? OR k.nama_kelas LIKE ?)';$args=['%'.$search.'%','%'.$search.'%','%'.$search.'%'];}
$joins=' FROM ak_kenaikan_detail d JOIN siswa s ON s.nis=d.nis JOIN ak_anggota_kelas a ON a.id=d.id_anggota_asal JOIN kelas k ON k.id_kelas=a.id_kelas JOIN ak_kenaikan_batch b ON b.id=d.id_batch JOIN tahun_ajaran t ON t.id_tahun_ajaran=d.periode_asal';
$total=(int)ak_query('SELECT COUNT(*)'.$joins.' WHERE '.$where,$args)->fetchColumn();[$page,$pages,$offset]=crud_page_bounds($total);
?><section class="panel"><h2>Daftar alumni</h2><p>Kelulusan ditetapkan melalui pratinjau Naik Kelas. Catatan siswa dan rapor historis tetap disimpan. Catatan dengan tanggal berlaku mendatang ditandai calon alumni.</p><form method="get" class="form-grid"><?php ak_hidden('view','alumni');ak_field('q','Cari NIS / nama / kelas',$search,'search',false);?><button class="secondary">Cari</button></form><div class="actions"><a class="button secondary" href="<?=e(ak_link('kenaikan'))?>">Naik Kelas</a></div><div class="table-scroll"><table><thead><tr><th>NIS</th><th>Nama</th><th>Kelas terakhir</th><th>Tahun</th><th>Berlaku</th><th>Status</th><th>Batch</th></tr></thead><tbody><?php foreach(ak_rows('SELECT d.*,s.nama_siswa,k.nama_kelas,t.tahun_ajaran'.$joins.' WHERE '.$where." ORDER BY d.tanggal_berlaku DESC,d.id DESC LIMIT 20 OFFSET $offset",$args)as $r):?><tr><td><?=e($r['nis'])?></td><td><?=e($r['nama_siswa'])?></td><td><?=e($r['nama_kelas'])?></td><td><?=e($r['tahun_ajaran'])?></td><td><?=e($r['tanggal_berlaku'])?></td><td><?=$r['tanggal_berlaku']<=date('Y-m-d')?'Alumni':'Calon alumni'?></td><td><a href="<?=e(ak_link('kenaikan',['batch'=>$r['id_batch']]))?>">#<?=e($r['id_batch'])?></a></td></tr><?php endforeach;if(!$total):?><tr><td colspan="7">Belum ada alumni yang cocok dengan filter.</td></tr><?php endif;?></tbody></table></div><?php crud_pager($page,$pages,$total);?></section>
